import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { ExternalLink, Save, RefreshCw, Info } from 'lucide-react';
import '../styles/Dashboard.css';

const Dashboard = () => {
    const [endpoint, setEndpoint] = useState('');
    const [isSaved, setIsSaved] = useState(false);
    const [loading, setLoading] = useState(false);

    // Load saved endpoint from local storage or DB on mount
    useEffect(() => {
        const savedUrl = localStorage.getItem('hasura_endpoint');
        if (savedUrl) {
            setEndpoint(savedUrl);
            setIsSaved(true);
        }
    }, []);

    const handleSave = (e) => {
        e.preventDefault();
        if (!endpoint.includes('https://')) {
            alert("Please enter a valid HTTPS Hasura endpoint.");
            return;
        }
        setLoading(true);
        // Simulate API call to save to backend
        setTimeout(() => {
            localStorage.setItem('hasura_endpoint', endpoint);
            setIsSaved(true);
            setLoading(false);
        }, 800);
    };

    const handleReset = () => {
        if (window.confirm("Are you sure you want to change your endpoint?")) {
            setIsSaved(false);
        }
    };

    // Construct the Console URL for the Iframe
    const consoleUrl = `https://console.hasura.io/console/graphiql?endpoint=${endpoint}`;

    return (
        <div className="dashboard-container">
            <AnimatePresence mode="wait">
                {!isSaved ? (
                    /* --- STATE 1: ASK FOR LINK --- */
                    <motion.div
                        key="setup"
                        className="dashboard-setup"
                        initial={{ opacity: 0, scale: 0.95 }}
                        animate={{ opacity: 1, scale: 1 }}
                        exit={{ opacity: 0, scale: 0.95 }}
                    >
                        <div className="setup-card">
                            <div className="setup-icon">
                                <RefreshCw size={32} />
                            </div>
                            <h2>Connect Your Data Layer</h2>
                            <p>Enter your Hasura GraphQL endpoint to manage your schema and test queries directly from WebVox.</p>

                            <form onSubmit={handleSave}>
                                <div className="form-group">
                                    <input
                                        type="url"
                                        placeholder="https://your-project.hasura.app/v1/graphql"
                                        value={endpoint}
                                        onChange={(e) => setEndpoint(e.target.value)}
                                        required
                                        className="form-control"
                                    />
                                </div>
                                <button type="submit" className="btn-primary" disabled={loading}>
                                    {loading ? 'Validating...' : 'Connect Console'}
                                </button>
                            </form>

                            <div className="setup-tip">
                                <Info size={16} />
                                <span>You can find this URL in your Hasura Cloud project settings.</span>
                            </div>
                        </div>
                    </motion.div>
                ) : (
                    /* --- STATE 2: ACTIVE CONSOLE --- */
                    <motion.div
                        key="console"
                        className="dashboard-active"
                        initial={{ opacity: 0 }}
                        animate={{ opacity: 1 }}
                    >
                        {/* Dashboard Sidebar/Header */}
                        <header className="console-header">
                            <div className="header-info">
                                <h3>Hasura Explorer</h3>
                                <code>{endpoint}</code>
                            </div>
                            <div className="header-actions">
                                <button onClick={handleReset} className="btn-icon" title="Change Endpoint">
                                    <RefreshCw size={18} />
                                </button>
                                <a href={endpoint} target="_blank" rel="noreferrer" className="btn-icon" title="Open API Link">
                                    <ExternalLink size={18} />
                                </a>
                                <button className="btn-save-status">
                                    <Save size={18} />
                                    Saved
                                </button>
                            </div>
                        </header>

                        {/* The Iframe Console */}
                        <div className="iframe-wrapper">
                            <iframe
                                src={consoleUrl}
                                title="Hasura Console"
                                frameBorder="0"
                                width="100%"
                                height="100%"
                                allow="clipboard-read; clipboard-write"
                            />
                        </div>
                    </motion.div>
                )}
            </AnimatePresence>
        </div>
    );
};

export default Dashboard;
